-- Auto-generated by backfill-embeddings.ts pre-flight check
-- Sets clip_embedding to 768-dim to match andreasjansson/clip-features actual output
ALTER TABLE public.products DROP COLUMN IF EXISTS clip_embedding;
ALTER TABLE public.products ADD COLUMN clip_embedding extensions.vector(768);

DROP FUNCTION IF EXISTS public.search_products_by_embedding(extensions.vector(1024), float, integer);
DROP FUNCTION IF EXISTS public.search_products_by_embedding(extensions.vector(512), float, integer);

CREATE OR REPLACE FUNCTION public.search_products_by_embedding(
  query_embedding extensions.vector(768),
  match_threshold FLOAT DEFAULT 0.5,
  match_count INTEGER DEFAULT 15
)
RETURNS TABLE (
  id UUID,
  name TEXT,
  retailer TEXT,
  price NUMERIC,
  image_url TEXT,
  affiliate_url TEXT,
  category TEXT,
  style_tags TEXT[],
  room_types TEXT[],
  similarity FLOAT
)
LANGUAGE plpgsql
AS $$
BEGIN
  RETURN QUERY
  SELECT p.id, p.name, p.retailer, p.price, p.image_url,
         p.affiliate_url, p.category, p.style_tags, p.room_types,
         1 - (p.clip_embedding <=> query_embedding) AS similarity
  FROM products p
  WHERE p.clip_embedding IS NOT NULL
    AND 1 - (p.clip_embedding <=> query_embedding) > match_threshold
  ORDER BY p.clip_embedding <=> query_embedding
  LIMIT match_count;
END;
$$;
